contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry exercising create; we don't assume this contract is a program operator.
    // We take encodedParameters and ownedBy as arbitrary inputs.
    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        require(true);

        // Read the prerequisites from the factory BEFORE attempting create.
        address beforeRoundImpl = c.roundImplementation(); if (__ESBMC_reverted()) return;
        address beforeAllo = c.alloSettings(); if (__ESBMC_reverted()) return;

        // Attempt the potentially-reverting create call and record outcome.
        bool reverted;
        address created;
        address addr = c.create(encodedParameters, ownedBy); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            created = address(0);
        } else {
            reverted = false;
            created = addr;
        }

        // General rule: if create returned a nonzero address (succeeded) then both prerequisites
        // were nonzero before the call. This asserts that successful creation implies the factory
        // had roundImplementation and alloSettings set prior to the create.
        assert(!(created != address(0)) || (beforeRoundImpl != address(0) && beforeAllo != address(0)));
    }

    receive() external payable {}
}

